test('overdueInvoices most overdue first', () => {
  const invoices = [];

  // Issue 2025-10-14, NET14 → due 2025-10-28, overdue by 2 days on 2025-10-30
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-14',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  invoices.push(issueInvoice(inv1, []).value);

  // Issue 2025-10-05, NET14 → due 2025-10-19, overdue by 11 days on 2025-10-30
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  invoices.push(issueInvoice(inv2, ['INV-2025-0001']).value);

  // Issue 2025-10-10, NET14 → due 2025-10-24, overdue by 6 days on 2025-10-30
  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  invoices.push(issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value);

  const result = overdueInvoices(invoices, '2025-10-30');
  assert.equal(result[0].daysOverdue, 11);
  assert.equal(result[1].daysOverdue, 6);
  assert.equal(result[2].daysOverdue, 2);
