  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv3, ['INV-2025-0001']).value;
  const totals = invoiceTotals(issued2);
  const paid = recordPayment(issued2, { amount: totals.total, date: '2025-10-08' }).value;

  const result = overdueInvoices([draft, issued, paid], '2025-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
