  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2020-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = lateFee(issued, '2025-10-07');
  const totals = invoiceTotals(issued);
  // Very long overdue period
  assert.ok(result > 0);
  assert.ok(result > totals.total);
});

