import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('overdueInvoices returns empty array for empty invoice list', () => {
  const result = overdueInvoices([], '2025-10-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no invoices are overdue', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoices with dueDate before asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices with dueDate after asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partialPaid = recordPayment(issued, { amount: 2000, date: '2025-10-08' }).value;

  const result = overdueInvoices([partialPaid], '2025-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total - 2000);
});

test('overdueInvoices excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = overdueInvoices([draft], '2025-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2025-10-08' }).value;

  const result = overdueInvoices([paid], '2025-10-20');
  assert.deepEqual(result, []);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-22');
  assert.equal(result[0].daysOverdue, 7);
});

test('overdueInvoices includes customerId in result', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-20');
  assert.equal(result[0].customerId, 'C-002');
});

test('overdueInvoices includes dueDate in result', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-20');
  assert.equal(result[0].dueDate, '2025-10-15');
});

test('overdueInvoices includes due amount in result', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);

  const result = overdueInvoices([issued], '2025-10-20');
  assert.equal(result[0].due, totals.total);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value;

  const result = overdueInvoices([issued1, issued2, issued3], '2025-10-30');
  assert.equal(result.length, 3);
  assert.equal(result[0].number, issued2.number);
  assert.equal(result[0].daysOverdue, 11);
  assert.equal(result[1].number, issued3.number);
  assert.equal(result[1].daysOverdue, 9);
  assert.equal(result[2].number, issued1.number);
  assert.equal(result[2].daysOverdue, 6);
});

test('overdueInvoices most overdue first', () => {
  const invoices = [];

  // Issue 2025-10-14, NET14 → due 2025-10-28, overdue by 2 days on 2025-10-30
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-14',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  invoices.push(issueInvoice(inv1, []).value);

  // Issue 2025-10-05, NET14 → due 2025-10-19, overdue by 11 days on 2025-10-30
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  invoices.push(issueInvoice(inv2, ['INV-2025-0001']).value);

  // Issue 2025-10-10, NET14 → due 2025-10-24, overdue by 6 days on 2025-10-30
  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  invoices.push(issueInvoice(inv3, ['INV-2025-0001', 'INV-2025-0002']).value);

  const result = overdueInvoices(invoices, '2025-10-30');
  assert.equal(result[0].daysOverdue, 11);
  assert.equal(result[1].daysOverdue, 6);
  assert.equal(result[2].daysOverdue, 2);
});

test('overdueInvoices with partially paid invoices shows correct due amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partialPaid = recordPayment(issued, { amount: 5000, date: '2025-10-08' }).value;

  const result = overdueInvoices([partialPaid], '2025-10-20');
  assert.equal(result[0].due, totals.total - 5000);
  assert.equal(result[0].due, balanceDue(partialPaid));
});

test('overdueInvoices with multiple overdue invoices', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: 'C-001',
      issueDate: `2025-10-${String(i).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value;
    const existing = invoices.map((x) => x.number).filter((n) => n);
    invoices.push(issueInvoice(inv, existing).value);
  }

  const result = overdueInvoices(invoices, '2025-11-01');
  assert.equal(result.length, 5);
  for (let i = 0; i < result.length - 1; i++) {
    assert.ok(result[i].daysOverdue >= result[i + 1].daysOverdue);
  }
});

test('overdueInvoices with mixed invoice statuses', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv2, []).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv3, ['INV-2025-0001']).value;
  const totals = invoiceTotals(issued2);
  const paid = recordPayment(issued2, { amount: totals.total, date: '2025-10-08' }).value;

  const result = overdueInvoices([draft, issued, paid], '2025-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

test('overdueInvoices calculates correct daysOverdue for various dates', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  // dueDate is 2025-10-15
  const result1 = overdueInvoices([issued], '2025-10-16');
  assert.equal(result1[0].daysOverdue, 1);

  const result2 = overdueInvoices([issued], '2025-10-20');
  assert.equal(result2[0].daysOverdue, 5);

  const result3 = overdueInvoices([issued], '2025-11-15');
  assert.equal(result3[0].daysOverdue, 31);
});

test('overdueInvoices with EOM payment terms', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  }).value;
  const issued = issueInvoice(inv, []).value;

  // dueDate is 2025-10-31
  const result = overdueInvoices([issued], '2025-11-05');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 5);
});

test('overdueInvoices with different customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = overdueInvoices([issued1, issued2], '2025-10-20');
  assert.equal(result.length, 2);
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-002');
});

test('overdueInvoices preserves invoice number format', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-20');
  assert.equal(result[0].number, 'INV-2025-0001');
});

test('overdueInvoices with no overdue but future invoices', () => {
  const invoices = [];

  // Issue date 2025-10-05, due date 2025-10-19
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  invoices.push(issueInvoice(inv1, []).value);

  // Issue date 2025-10-15, due date 2025-11-14
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;
  invoices.push(issueInvoice(inv2, ['INV-2025-0001']).value);

  const result = overdueInvoices(invoices, '2025-10-19');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns correct structure', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-20');
  assert.equal(result.length, 1);
  const item = result[0];

  assert.ok(item.hasOwnProperty('number'));
  assert.ok(item.hasOwnProperty('customerId'));
  assert.ok(item.hasOwnProperty('dueDate'));
  assert.ok(item.hasOwnProperty('daysOverdue'));
  assert.ok(item.hasOwnProperty('due'));

  assert.equal(typeof item.number, 'string');
  assert.equal(typeof item.customerId, 'string');
  assert.equal(typeof item.dueDate, 'string');
  assert.equal(typeof item.daysOverdue, 'number');
  assert.equal(typeof item.due, 'number');
});

test('overdueInvoices does not mutate input invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;
  const invoices = [issued];
  const originalStatus = issued.status;
  const originalNumber = issued.number;

  overdueInvoices(invoices, '2025-10-20');

  assert.equal(invoices[0].status, originalStatus);
  assert.equal(invoices[0].number, originalNumber);
});

test('overdueInvoices with large daysOverdue values', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2020-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-07');
  assert.equal(result.length, 1);
  assert.ok(result[0].daysOverdue > 1900);
});

test('vatSummary returns empty array for empty invoice list', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary returns empty array when no issued invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = vatSummary([draft]);
  assert.deepEqual(result, []);
});

test('vatSummary includes issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const partialPaid = recordPayment(issued, { amount: 2000, date: '2025-10-08' }).value;

  const result = vatSummary([partialPaid]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary includes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2025-10-08' }).value;

  const result = vatSummary([paid]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary excludes draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = vatSummary([draft]);
  assert.deepEqual(result, []);
});

test('vatSummary calculates base and vat correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // C-001 is gold tier (5% discount): 10 * 8500 * 0.95
  assert.equal(result[0].base, 80750);
  assert.equal(result[0].vat, 16958);
});

test('vatSummary includes multiple VAT rates sorted high to low', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
