import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('overdueInvoices returns empty array for empty invoice list', () => {
  const result = overdueInvoices([], '2025-10-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no invoices are overdue', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-10');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoices with dueDate before asOf', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const result = overdueInvoices([issued], '2025-10-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, issued.number);
});

